  const state = makeWorkspace();
  state.workspace.select({ id: \"sync\", progressFeed: feed });
  assert.deepEqual(state.history.map(x => x.frame), [{ done: 2, decoded: true }]);
  assert.deepEqual(state.displayed.map(x => x.frame), [{ done: 2, decoded: true }]);
  feed.emit({ done: 3 });
  assert.deepEqual(state.displayed.map(x => x.frame.done), [2, 3]);
